/// <reference types="vite/client" />

// Déclarations pour les modules importés manuellement
declare module '*.svg' {
  const content: string;
  export default content;
}

declare module '*.png' {
  const content: string;
  export default content;
}

declare module '*.jpg' {
  const content: string;
  export default content;
}

declare module '*.jpeg' {
  const content: string;
  export default content;
}

declare module '*.gif' {
  const content: string;
  export default content;
}

declare module '*.webp' {
  const content: string;
  export default content;
}

// Déclaration pour les modules CSS
declare module '*.css' {
  const content: string;
  export default content;
}